import { CatalystAuthenticationError } from './error.js';
export async function assertPopupAuthAllowed() {
    if (typeof window === 'undefined' || typeof window.open !== 'function') {
        throw new CatalystAuthenticationError('POPUP_NOT_SUPPORTED', 'window.open is not available in this environment. Popups cannot be opened.');
    }
    if (typeof indexedDB === 'undefined') {
        throw new CatalystAuthenticationError('IDB_NOT_SUPPORTED', 'IndexedDB is not available in this environment. The OAuth token cannot be stored.');
    }
    try {
        await new Promise((resolve, reject) => {
            const timer = setTimeout(() => reject(new Error('IndexedDB open timed out after 2000ms')), 2000);
            const req = indexedDB.open('__zc_idb_check__');
            req.onupgradeneeded = () => {
            };
            req.onsuccess = () => {
                clearTimeout(timer);
                const db = req.result;
                if (db) {
                    db.close();
                }
                resolve();
            };
            req.onerror = () => {
                clearTimeout(timer);
                reject(req.error ?? new Error('IndexedDB open failed'));
            };
            req.onblocked = () => {
                clearTimeout(timer);
                reject(new Error('IndexedDB open was blocked'));
            };
        });
    }
    catch (err) {
        throw new CatalystAuthenticationError('IDB_ACCESS_DENIED', `IndexedDB could not be opened. This may be caused by private/incognito mode or a security policy. Detail: ${err instanceof Error ? err.message : String(err)}`);
    }
}
